fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    let mut chars = txt.chars();
    // Get the last character, if any
    let last_char = match chars.next_back() {
        Some(c) => c,
        None => return false, // empty string
    };

    // Check if last_char is an ASCII alphabetic letter
    if !last_char.is_ascii_alphabetic() {
        return false;
    }

    // Now check the condition on preceding character:
    // if txt has exactly one character, return true
    // else check if char before last is a space ' '

    // Try to get the char before last by creating a double-ended iterator again
    // and moving ahead until the second last character.
    // Since we already consumed last_char, do it again from the start:

    let mut chars_rev = txt.chars().rev();
    // skip last character (already taken)
    chars_rev.next();

    match chars_rev.next() {
        None => true,           // only one char in string
        Some(prev_char) => prev_char == ' ', // must be space
    }
}